import{_ as t,a as o}from"./chunks/px4_arch_fc_companion.DaI9nYt5.js";import{_ as a,c as r,o as s,al as l}from"./chunks/framework.CT7RwC5a.js";const f=JSON.parse('{"title":"PX4 아키텍쳐","description":"","frontmatter":{},"headers":[],"relativePath":"ko/concept/px4_systems_architecture.md","filePath":"ko/concept/px4_systems_architecture.md"}'),i={name:"ko/concept/px4_systems_architecture.md"};function n(c,e,m,h,u,p){return s(),r("div",null,e[0]||(e[0]=[l('<h1 id="px4-아키텍쳐" tabindex="-1">PX4 아키텍쳐 <a class="header-anchor" href="#px4-아키텍쳐" aria-label="Permalink to &quot;PX4 아키텍쳐&quot;">​</a></h1><p>아래 섹션에서는 &quot;일반적인&quot; PX4 시스템의 하드웨어와 소프트웨어 개요를 제공합니다. 하나는 비행 콘트롤러만 있는 것이고 다른 하나는 비행 컨트롤러와 보조 컴퓨터(&quot;미션 컴퓨터&quot;라고도 함)가 있습니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 아키텍처 개요(../concept/architecture.md)는 비행 스택과 미들웨어에 대한 정보를 제공합니다. 오프보드 API는 ROS(../ros/index.md)와 MAVSDK(<a href="https://mavsdk.mavlink.io/main/en/" target="_blank" rel="noreferrer">https://mavsdk.mavlink.io/main/en/</a>)에서 다루어집니다.</p></div><h2 id="비행-콘트롤러" tabindex="-1">비행 콘트롤러 <a class="header-anchor" href="#비행-콘트롤러" aria-label="Permalink to &quot;비행 콘트롤러&quot;">​</a></h2><p>아래 다이어그램은 비행 콘트롤러 기반 PX4 시스템 개요입니다.</p><p><img src="'+t+'" alt="PX4 구조: 비행 컨트롤러 단독 운용 시스템"></p><p>하드웨어 구성</p><ul><li>(PX4 비행 제어 소프트웨어를 실행하는) <a href="./../flight_controller/">비행 컨트롤러</a>. 콘트롤러에는 대부분 내부 IMU, 나침반 및 기압계가 포함되어 있습니다.</li><li><a href="./../peripherals/esc_motors.html">Motor ESCs</a> connected to <a href="./../peripherals/pwm_escs_and_servo.html">PWM outputs</a>, <a href="./../dronecan/escs.html">DroneCAN</a> (DroneCAN allows two-way communication, not single direction as shown) or some other bus.</li><li>Sensors (<a href="./../gps_compass/">GPS</a>, <a href="./../gps_compass/">compass</a>, distance sensors, barometers, optical flow, barometers, ADSB transponders, etc.) connected via I2C, SPI, CAN, UART etc.</li><li><a href="./../camera/">Camera</a> or other payload. 카메라는 PWM 출력에 연결하거나 MAVLink로 연결할 수 있습니다.</li><li><a href="./../telemetry/">Telemetry radios</a> for connecting to a ground station computer/software.</li><li><a href="./../getting_started/rc_transmitter_receiver.html">RC Control System</a> for manual control</li></ul><p>도표의 왼쪽은 소프트웨어 스택을 보여주며, 이는 도표의 하드웨어 구성 요소들과 (대략적으로) 수평으로 정렬되어 있습니다.</p><ul><li>The ground station computer typically runs <a href="./../getting_started/px4_basic_concepts.html#qgc">QGroundControl</a> (or some other ground station software). It may also run robotics software like <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a> or <a href="./../ros/">ROS</a>.</li><li>The PX4 flight stack running on the flight controller includes <a href="./../modules/modules_driver.html">drivers</a>, <a href="./../modules/modules_communication.html">comms modules</a>, <a href="./../modules/modules_controller.html">controllers</a>, <a href="./../modules/modules_controller.html">estimators</a> and other <a href="./../modules/modules_main.html">middleware and system modules</a>.</li></ul><h2 id="비행-콘트롤러와-보조-컴퓨터" tabindex="-1">비행 콘트롤러와 보조 컴퓨터 <a class="header-anchor" href="#비행-콘트롤러와-보조-컴퓨터" aria-label="Permalink to &quot;비행 콘트롤러와 보조 컴퓨터&quot;">​</a></h2><p>아래 다이어그램은 비행 콘트롤러와 보조 컴퓨터(여기서는 &quot;임무 컴퓨터&quot;라고 함)를 포함하는 PX4 시스템을 나타냅니다.</p><p><img src="'+o+'" alt="PX4 architecture - FC + Companion Computer"></p><p>The flight controller runs the normal PX4 flight stack, while a companion computer provides advanced features that utilise <a href="./../computer_vision/">computer vision</a>. The two systems are connected using a fast serial or IP link, and typically communicate using the <a href="https://mavlink.io/en/" target="_blank" rel="noreferrer">MAVLink protocol</a>. Communications with the ground stations and the cloud are usually routed via the companion computer (e.g. using the <a href="https://github.com/mavlink-router/mavlink-router" target="_blank" rel="noreferrer">MAVLink Router</a> (from Intel)).</p><p>PX4 기반 시스템에서는 보조 컴퓨터에 리눅스 운영체제를 쓰는 경우가 많습니다. Linux는 NuttX보다 &quot;일반&quot; 소프트웨어 개발을 위한 플랫폼입니다. 많은 Linux 개발자와 유용한 소프트웨어가 이미 개발되어 있습니다(예: 컴퓨터 비전, 통신, 클라우드 통합, 하드웨어 드라이버용). 보조 컴퓨터는 때때로 같은 이유로 Android를 사용합니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>이 다이어그램은 LTE를 통해 클라우드 또는 지상국과 연결하는 방식을 보여주며, 이 방식은 여러 PX4 기반 시스템에서 사용되어 왔습니다. PX4는 특별히 LTE와 클라우드 통합을 위한 소프트웨어를 제공하지 않습니다(사용자 맞춤형 개발이 필요함).</p></div>',16)]))}const k=a(i,[["render",n]]);export{f as __pageData,k as default};
